    CONSTRAINT auth_oauth_refresh_digest_check CHECK ((((octet_length(digest) >= 1) AND (octet_length(digest) <= 64)) AND (digest = btrim(digest, ((((((((((((((((((((((((chr(9) || chr(10)) || chr(11)) || chr(12)) || chr(13)) || chr(32)) || chr(160)) || chr(5760)) || chr(8192)) || chr(8193)) || chr(8194)) || chr(8195)) || chr(8196)) || chr(8197)) || chr(8198)) || chr(8199)) || chr(8200)) || chr(8201)) || chr(8202)) || chr(8232)) || chr(8233)) || chr(8239)) || chr(8287)) || chr(12288)) || chr(65279)))) AND (digest !~ ((((((('['::text || chr(1)) || '-'::text) || chr(31)) || chr(127)) || '-'::text) || chr(159)) || ']'::text)))),
    CONSTRAINT auth_oauth_refresh_digest_check1 CHECK ((digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT auth_oauth_refresh_grant_id_check CHECK ((((octet_length(grant_id) >= 1) AND (octet_length(grant_id) <= 36)) AND (grant_id = btrim(grant_id, ((((((((((((((((((((((((chr(9) || chr(10)) || chr(11)) || chr(12)) || chr(13)) || chr(32)) || chr(160)) || chr(5760)) || chr(8192)) || chr(8193)) || chr(8194)) || chr(8195)) || chr(8196)) || chr(8197)) || chr(8198)) || chr(8199)) || chr(8200)) || chr(8201)) || chr(8202)) || chr(8232)) || chr(8233)) || chr(8239)) || chr(8287)) || chr(12288)) || chr(65279)))) AND (grant_id !~ ((((((('['::text || chr(1)) || '-'::text) || chr(31)) || chr(127)) || '-'::text) || chr(159)) || ']'::text)))),
    CONSTRAINT auth_oauth_refresh_grant_id_check1 CHECK ((grant_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT auth_oauth_refresh_issued_at_check CHECK (((issued_at >= 0) AND (issued_at <= '8640000000000000'::bigint))),
    CONSTRAINT auth_oauth_refresh_used_at_check CHECK (((used_at IS NULL) OR ((used_at >= 0) AND (used_at <= '8640000000000000'::bigint))))
);
